export function artUse(name,x=0,y=0,size=120){return `<use href="#art-${name}" x="${x}" y="${y}" width="${size}" height="${size}"/>`;}
export function foodArt(place){const f=place.food||'';return /스시|해산/.test(f)?'sushi':/라멘|소바/.test(f)?'noodles':/요리|에키벤/.test(f)?'bento':/차|커피|카페/.test(f)?'tea':'sweet';}
export function illustration(name,{postcard=false}={}){return `<svg viewBox="0 0 ${postcard?'300 160':'120 120'}" aria-hidden="true">${postcard?`<rect width="300" height="160" rx="16" fill="#e6ead6"/><circle cx="228" cy="37" r="24" fill="#f3dba0"/><path d="M0 104q55-30 113 0t115-7t72 3v60H0" fill="#c7d7b7"/><path d="M0 134q75-25 150 0t150-7v33H0" fill="#b9ccaa"/><path d="m0 141 120-4 105 23H0" fill="#e9dfba"/>${artUse('tree',9,42,85)}${artUse(name,95,3,145)}${artUse('tree',230,65,65)}`:artUse(name)}</svg>`;}
